import { createReadStream, writeFileSync } from 'node:fs'
import { createInterface } from 'node:readline'

type WriteKind = 'db' | 'wal' | 'sqliteTemp'
type WriteTotals = Record<WriteKind, number> & { calls: number }
const [input, output] = process.argv.slice(2)
if (!input || !output) throw new Error('usage: room-write-trace.ts <strace.log> <report.json>')

// Count completed bytes only within the frozen harness workload markers.
// strace -f may split a syscall around another thread's output; retain its
// original workload and file kind until that thread resumes the same syscall.
const totals: Record<string, WriteTotals> = {}
const pending = new Map<string, { workload: string; kind: WriteKind }>()
const completed = new Set<string>()
let active: string | undefined
const lines = createInterface({ input: createReadStream(input), crlfDelay: Infinity })
for await (const line of lines) {
  const pid = line.split(' ', 1)[0]!
  const resumed = /<\.\.\. (pwrite64|write|writev) resumed>/.exec(line)
  const pendingKey = `${pid}:${resumed?.[1]}`
  const saved = resumed ? pending.get(pendingKey) : undefined
  if (saved) pending.delete(pendingKey)
  const marker = /OA_TRACE_(BEGIN|END) ([24])/.exec(line)
  if (marker) {
    const workload = marker[2]!
    if (marker[1] === 'BEGIN') {
      if (active || totals[workload]) throw new Error('Repeated or overlapping workload markers')
      active = workload
      totals[workload] = { db: 0, wal: 0, sqliteTemp: 0, calls: 0 }
    } else {
      if (active !== workload) throw new Error('Mismatched workload end marker')
      completed.add(workload)
      active = undefined
    }
    continue
  }
  const database = /(pwrite64|write|writev)\(\d+<[^>]+\/probe\.db(-wal)?>/.exec(line)
  const temporary = /(pwrite64|write|writev)\(\d+<[^>]+\/etilqs_[^>]+>/.exec(line)
  let write = saved
  if (!write && active && (database || temporary)) {
    write = { workload: active, kind: temporary ? 'sqliteTemp' : database?.[2] ? 'wal' : 'db' }
    if (line.includes('<unfinished ...>')) {
      pending.set(`${pid}:${(temporary ?? database)![1]}`, write)
      continue
    }
  }
  if (!write) continue
  const bytes = /= (\d+)\s*$/.exec(line)
  if (!bytes) throw new Error(`Cannot parse completed database write: ${line}`)
  totals[write.workload]![write.kind] += Number(bytes[1])
  totals[write.workload]!.calls++
}
if (pending.size) throw new Error('Trace ended with unfinished database writes')
if (active || [...completed].sort().join(',') !== '2,4') throw new Error('Expected both completed workload marker pairs')
writeFileSync(output, `${JSON.stringify(totals, null, 2)}\n`)

diagnose-window.ts.source:
/** Diagnostic only: extra full-view projections invalidate all runtime timings. */
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { pathToFileURL } from 'node:url'

async function main() {
  const [rootArg, fixtureArg, outputArg, nameMode = 'matched'] = process.argv.slice(2)
  assert.ok(rootArg && fixtureArg && outputArg, 'usage: diagnose-window.ts ROOT FIXTURE OUTPUT [matched|override]')
  assert.ok(nameMode === 'matched' || nameMode === 'override')
  const root = resolve(rootArg)
  const fromRoot = (path: string) => import(pathToFileURL(resolve(root, path)).href)
  const [{ GameSession }, { runRoomWorkload }, { getHistoryRecordIdentity }] = await Promise.all([
    fromRoot('server/game/authoritative-session.ts'),
    fromRoot('scripts/bench/room-performance.ts'),
    fromRoot('shared/session/history-streams.ts'),
  ])
  const fixtureText = readFileSync(resolve(fixtureArg), 'utf8')
  const workload = JSON.parse(fixtureText)
  const rows: Record<string, any>[] = []
  const original = GameSession.prototype.buildSyncPayload
  GameSession.prototype.buildSyncPayload = function (...args: any[]) {
    const output = Reflect.apply(original, this, args)
    const [response, viewer, mode = 'viewer', , windowed = false] = args
    if (!windowed || mode === 'debug') return output
    const source = new Set(response.state.publicEventArchive)
    const selectedGroups = new Set(output.historyWindow.operationGroupIds)
    const summarize = (packets: object[]) => ({ packets: packets.length,
      reusedSourcePackets: packets.filter(packet => source.has(packet)).length,
      allocatedPackets: packets.filter(packet => !source.has(packet)).length })
    // A separate full-view invocation exposes allocations discarded by the window.
    // It is diagnostic work, never included in timing acceptance.
    const fullArgs = [...args]
    fullArgs[4] = false
    const full = Reflect.apply(original, this, fullArgs)
    const outside = full.state.publicEventArchive.filter((packet: object) => {
      const identity = getHistoryRecordIdentity(packet)
      assert.ok(identity, 'Every full-view archive packet must retain history identity')
      return !selectedGroups.has(identity.operationGroupId)
    })
    rows.push({ callIndex: rows.length, round: response.state.round, viewer, mode,
      canonicalPackets: source.size, selectedGroups: selectedGroups.size,
      window: summarize(output.state.publicEventArchive), full: summarize(full.state.publicEventArchive),
      outsideWindow: summarize(outside) })
    return output
  }
  let run
  try { run = runRoomWorkload(workload, { nameMode }) } finally {
    GameSession.prototype.buildSyncPayload = original
  }
  const committed = run.commandSamples.filter((sample: any) => sample.classification === 'committed')
  assert.equal(rows.length, committed.length * workload.players, 'Exactly one observed window per committed command and seat')
  for (let index = 0; index < committed.length; index += 1) {
    const group = rows.slice(index * workload.players, (index + 1) * workload.players)
    assert.equal(new Set(group.map(row => row.viewer)).size, workload.players)
    for (const row of group) row.commandIndex = committed[index].commandIndex
  }
  const total = (selected: typeof rows) => Object.fromEntries(['window', 'full', 'outsideWindow'].map(scope => [scope,
    Object.fromEntries(['packets', 'reusedSourcePackets', 'allocatedPackets'].map(key => [key,
      selected.reduce((sum, row) => sum + row[scope][key], 0)]))]))
  const sourcePaths = ['scripts/bench/room-performance.ts', 'server/game/authoritative-session.ts',
    'server/game/custom-session-executor.ts', 'shared/session/sync-payload.ts',
    'shared/session/history-window.ts', 'shared/projections/serialized-state.ts',
    'shared/projections/history-names.ts', 'shared/projections/history-record-identity.ts']
  const sha = (text: string) => createHash('sha256').update(text).digest('hex')
  const result = { mode: 'diagnostic-reference-identity', node: process.version, root, nameMode,
    fixture: resolve(fixtureArg), fixtureSha256: sha(fixtureText), preparation: workload.preparation,
    sourceSha256: Object.fromEntries(sourcePaths.map(path => [path, sha(readFileSync(resolve(root, path), 'utf8'))])),
    commands: run.commands, committedCommands: committed.length, viewers: workload.players,
    projectionCalls: rows.length, totals: total(rows),
    byRound: Object.fromEntries([...new Set(rows.map(row => row.round))].map(round => [round, total(rows.filter(row => row.round === round))])),
    rows, hashes: run.hashes, classifications: run.classifications,
    interpretation: 'Counts packet occurrences, not heap objects or bytes. allocatedPackets means a returned packet is not any source response archive packet. Extra full-view calls reveal outside-window copies but duplicate all projection work. No measured latency/CPU values are retained; this is not timing evidence. Preserved source references prove packet reuse, not elimination of wrapper arrays or full visibility/sequence scans.' }
  writeFileSync(resolve(outputArg), JSON.stringify(result, null, 2) + '\n', { flag: 'wx' })
  console.log(JSON.stringify({ output: resolve(outputArg), projectionCalls: rows.length, totals: result.totals }))
}
void main()

assemble-history.py.source:
#!/usr/bin/env python3
"""Assemble retained history-projection evidence; run only after all sampling/checks.

  python3 /tmp/open-agricola-history.WgSy7A/assemble-history.py
  python3 assemble-history.py --output /tmp/history-results-review.json
  python3 assemble-history.py --expand /path/to/results.json --output /tmp/expanded.json

The default output is /home/xxh/open-agricola/docs/performance/room-history-projection-results.json.
An existing output requires --replace. This program does not run games, tests,
benchmarks, analyzers, services, or acceptance calculations. Failed verdicts are
retained. Only read-only git commands are executed, to capture the exact patch.

Required runs/ inputs:
  history-thresholds.json; decision.json; capacity-contract.json
  {late-matched,late-override,stock2-matched,stock4-matched}-{baseline,control,final}-{1..5}.json
  {late-matched,late-override}-{archive,names}-{1..3}.json
  {archive,names}-history-comparison-3.json; final-history-comparison-5.json
  exact-byte-equality.json; exact-comparator-self-test.json
  {case}-{baseline,final}-exact.{json,jsonl}; {case}-final-exact-comparison.json
  {late-matched,late-override}-names-exact.{json,jsonl}; corresponding -comparison.json
  {baseline,final}-matched-broadcast-profile.json; {baseline,final}-matched.cpuprofile
  window-reference-{baseline,candidate}-matched.json
  {baseline,final}-writes.json; {baseline,final}-writes.trace; physical-write-verdict.json
  {baseline,final}-capacity.json; capacity-verdict.json
  main-fast.log (successful main-tree summary: 8338 passed)

decision.json must contain adopted (boolean), reason (nonempty string),
verification (object), and commands (object). All other decision fields survive.
verification.mainFast must contain passed:8338 and exitCode:0; candidate full-fast
is deliberately not required. Candidate focused/types/E2E evidence stays in the
provided verification metadata and original logs.
All additional completed runs/*.json and root/*.json artifacts are also retained,
as are SHA/size metadata for every root/runs *.log (including failures).
Tool source and source/fixture/harness manifests are embedded. Large JSON values
are interned losslessly; every original JSON artifact is reconstructed and checked
before writing. commandSamples share an interned template containing every field
except elapsedMs, paired with an equally sized elapsedMs vector; --expand restores
the complete rows. The raw original trace text is retained on disk and fingerprinted;
full trace byte equality is independently checked while streaming its SHA/size.
"""

import argparse
import hashlib
import json
import os
import re
import subprocess
import sys
import tempfile
from contextlib import ExitStack
from datetime import datetime, timezone
from pathlib import Path


CASES = ('late-matched', 'late-override', 'stock2-matched', 'stock4-matched')
BASE = '32f49e42'
FINAL = 'da0638cc'
SLICES = {'names': 'f8d1cf21', 'archive': 'e91f94a3'}
TOOLS = ('analyze-history.py', 'analyze-profile.py', 'diagnose-window.ts', 'compare-exact.py',
         'analyze-capacity.py', 'run-population.py', 'run-pairs.py', 'run-exact.py', 'assemble-history.py')
HARNESSES = ('room-performance.ts', 'broadcast-performance.ts', 'late-game-capacity.ts',
             'late-game-workload.ts', 'room-write-trace.ts', 'tsconfig.performance.json')
REF = '$roomHistoryJsonRef'
SAMPLES = '$roomHistoryCommandSamples'


def require(condition, message):
    if not condition:
        raise ValueError(message)


def digest(data):
    return hashlib.sha256(data).hexdigest()


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False, allow_nan=False)


def parse(data):
    def pairs(entries):
        result = {}
        for key, value in entries:
            require(key not in result, f'Duplicate JSON key: {key}')
            result[key] = value
        return result
    def invalid(value):
        raise ValueError(f'Invalid JSON constant: {value}')
    return json.loads(data, object_pairs_hook=pairs, parse_constant=invalid)


def stamp(path):
    status = path.stat()
    return status.st_dev, status.st_ino, status.st_size, status.st_mtime_ns


class Inputs:
    def __init__(self, root):
        self.root = root
        self.stamps = {}
        self.json = {}
        self.meta = {}

    def key(self, path):
        return str(path.resolve().relative_to(self.root))

    def remember(self, path):
        path = path.resolve()
        before = stamp(path)
        require(self.stamps.get(path, before) == before, f'Input changed: {path}')
        self.stamps[path] = before
        return path

    def artifact(self, path, source=False):
        path = self.remember(path)
        hasher, size = hashlib.sha256(), 0
        with path.open('rb') as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b''):
                hasher.update(chunk)
                size += len(chunk)
        result = {'path': str(path), 'bytes': size, 'sha256': hasher.hexdigest()}
        if source:
            result['source'] = path.read_text()
        require(stamp(path) == self.stamps[path], f'Input changed while reading: {path}')
        return result

    def load(self, path):
        path = self.remember(path)
        key = self.key(path)
        if key not in self.json:
            data = path.read_bytes()
            self.json[key] = parse(data)
            self.meta[key] = {'path': str(path), 'bytes': len(data), 'sha256': digest(data)}
            require(stamp(path) == self.stamps[path], f'Input changed while reading: {path}')
        return self.json[key]

    def unchanged(self):
        for path, before in self.stamps.items():
            require(stamp(path) == before, f'Input changed during assembly: {path}')


class JsonPool:
    """Content-address complete reports and repeated arrays, without deleting fields."""
    def __init__(self):
        self.values = {}

    def encode(self, value, field=''):
        if field == 'commandSamples':
            require(isinstance(value, list) and all(isinstance(row, dict) and 'elapsedMs' in row for row in value),
                    'commandSamples must contain objects with an elapsedMs field')
        if not isinstance(value, (dict, list)):
            return value
        if isinstance(value, dict):
            require(REF not in value and SAMPLES not in value, 'Input uses a reserved encoding key')
            encoded = {key: self.encode(item, key) for key, item in value.items()}
        elif field == 'commandSamples':
            encoded = {SAMPLES: {
                'template': self.encode([{key: item for key, item in row.items() if key != 'elapsedMs'} for row in value], 'commandSampleTemplate'),
                'elapsedMs': self.encode([row['elapsedMs'] for row in value])}}
        else:
            encoded = [self.encode(item) for item in value]
        raw = canonical(value).encode()
        if len(raw) < 512 and field not in ('commandSamples', 'commandSampleTemplate', 'hashes', 'classifications', 'globalBijection'):
            return encoded
        key = digest(raw)
        if key in self.values:
            require(self.values[key] == encoded or canonical(self.decode(self.values[key])).encode() == raw,
                    f'JSON content-address collision: {key}')
        else:
            self.values[key] = encoded
        return {REF: key}

    def decode(self, value):
        if isinstance(value, dict):
            if REF in value:
                require(set(value) == {REF}, 'Malformed JSON reference marker')
                require(value[REF] in self.values, f'Unresolved JSON reference: {value[REF]}')
                return self.decode(self.values[value[REF]])
            if SAMPLES in value:
                require(set(value) == {SAMPLES} and isinstance(value[SAMPLES], dict)
                        and set(value[SAMPLES]) == {'template', 'elapsedMs'}, 'Malformed commandSamples marker')
                template, elapsed = (self.decode(value[SAMPLES][key]) for key in ('template', 'elapsedMs'))
                require(isinstance(template, list) and isinstance(elapsed, list) and len(template) == len(elapsed),
                        'commandSamples template/elapsedMs cardinality mismatch')
                require(all(isinstance(row, dict) and 'elapsedMs' not in row for row in template),
                        'commandSamples template contains an elapsedMs field or a non-object row')
                return [{**row, 'elapsedMs': duration} for row, duration in zip(template, elapsed)]
            return {key: self.decode(item) for key, item in value.items()}
        return [self.decode(item) for item in value] if isinstance(value, list) else value


def trace_group(inputs, paths):
    """Compare complete original bytes and fingerprint each trace in the same pass."""
    names = list(paths)
    before = {name: inputs.remember(path) for name, path in paths.items()}
    hashers = {name: hashlib.sha256() for name in names}
    sizes, lines = dict.fromkeys(names, 0), dict.fromkeys(names, 0)
    equal = True
    with ExitStack() as stack:
        streams = {name: stack.enter_context(path.open('rb')) for name, path in before.items()}
        while True:
            chunks = {name: stream.read(1024 * 1024) for name, stream in streams.items()}
            if not any(chunks.values()):
                break
            equal = equal and all(chunk == chunks[names[0]] for chunk in chunks.values())
            for name, chunk in chunks.items():
                hashers[name].update(chunk)
                sizes[name] += len(chunk)
                lines[name] += chunk.count(b'\n')
    return {'byteIdentical': equal, 'artifacts': {name: {
        'path': str(before[name]), 'sha256': hashers[name].hexdigest(),
        'bytes': sizes[name], 'lines': lines[name]} for name in names}}


def source_evidence(tree):
    def git(*arguments):
        return subprocess.check_output(['git', *arguments], cwd=tree)
    def commit(value):
        return git('rev-parse', '--verify', value + '^{commit}').decode().strip()
    baseline, combined = commit(BASE), commit(FINAL)
    patch = git('diff', '--binary', '--no-ext-diff', baseline, combined).decode()
    changed = git('diff', '--name-only', baseline, combined).decode().splitlines()
    production = [path for path in changed if path.startswith(('server/', 'shared/', 'client/'))
                  and '/__tests__/' not in path and not path.endswith(('.test.ts', '.test.tsx'))]
    baseline_files = set(git('ls-tree', '-r', '--name-only', baseline).decode().splitlines())
    files = {path: {'baselineSha256': digest(git('show', f'{baseline}:{path}')) if path in baseline_files else None,
                    'combinedSha256': digest(git('show', f'{combined}:{path}'))} for path in production}
    return {'baselineCommit': baseline, 'combinedCommit': combined,
            'sliceCommits': {name: commit(value) for name, value in SLICES.items()},
            'combinedPatch': {'command': f'git diff --binary --no-ext-diff {baseline} {combined}',
                              'includes': 'Complete implementation and regression tests; benchmark harness is not in these commits.',
                              'sha256': digest(patch.encode()), 'bytes': len(patch.encode()), 'text': patch},
            'changedFiles': changed, 'productionFiles': files}


def build(root):
    runs = root / 'runs'
    inputs = Inputs(root)
    ref = lambda name: f'runs/{name}'
    populations = {}
    for prefix, cases, count in (('baseline', CASES, 5), ('archive', CASES[:2], 3),
                                  ('names', CASES[:2], 3), ('control', CASES, 5), ('final', CASES, 5)):
        populations[prefix] = {case: [ref(f'{case}-{prefix}-{index}.json') for index in range(1, count + 1)] for case in cases}
    required = {name for population in populations.values() for names in population.values() for name in names}
    fixed = ('history-thresholds.json', 'decision.json', 'capacity-contract.json',
             'archive-history-comparison-3.json', 'names-history-comparison-3.json', 'final-history-comparison-5.json',
             'exact-byte-equality.json', 'exact-comparator-self-test.json',
             'baseline-matched-broadcast-profile.json', 'final-matched-broadcast-profile.json',
             'window-reference-baseline-matched.json', 'window-reference-candidate-matched.json',
             'baseline-writes.json', 'final-writes.json', 'physical-write-verdict.json',
             'baseline-capacity.json', 'final-capacity.json', 'capacity-verdict.json')
    required.update(map(ref, fixed))
    exact_groups, exact_reports = {}, []
    for case in CASES:
        variants = ['baseline', 'final', *(['names'] if case in CASES[:2] else [])]
        exact_groups[case] = {variant: runs / f'{case}-{variant}-exact.jsonl' for variant in variants}
        for variant in variants:
            required.add(ref(f'{case}-{variant}-exact.json'))
            if variant != 'baseline':
                name = ref(f'{case}-{variant}-exact-comparison.json')
                required.add(name)
                exact_reports.append(name)
    missing = [name for name in sorted(required) if not (root / name).is_file()]
    missing += [str(path.relative_to(root)) for paths in exact_groups.values() for path in paths.values() if not path.is_file()]
    missing += [name for name in TOOLS if not (root / name).is_file()]
    missing += [f'runs/{name}' for name in ('main-fast.log', 'baseline-writes.trace', 'final-writes.trace',
                                           'baseline-matched.cpuprofile', 'final-matched.cpuprofile') if not (runs / name).is_file()]
    require(not missing, 'Missing required artifacts: ' + ', '.join(missing))
    for name in sorted(required):
        inputs.load(root / name)
    decision = inputs.json[ref('decision.json')]
    require(type(decision.get('adopted')) is bool and isinstance(decision.get('reason'), str) and decision['reason'].strip(),
            'decision.json needs adopted:boolean and reason:nonempty string')
    require(all(isinstance(decision.get(key), dict) for key in ('verification', 'commands')),
            'decision.json needs verification and commands objects')
    main_fast = decision['verification'].get('mainFast', {})
    require(main_fast.get('passed') == 8338 and main_fast.get('exitCode') == 0,
            'decision.verification.mainFast must record passed:8338 and exitCode:0')
    main_log = inputs.remember(runs / 'main-fast.log').read_text()
    main_log = re.sub(r'\x1b\[[0-?]*[ -/]*[@-~]', '', main_log)
    summaries = re.findall(r'^\s*Tests\s+([^\n]+)', main_log, re.MULTILINE)
    require(any(re.search(r'\b8338 passed\b', line) and not re.search(r'\b[1-9]\d* failed\b', line) for line in summaries),
            'main-fast.log does not contain the required successful 8338-test summary')

    # This inventory includes failed probes, smoke reports and any additional
    # completed validation/diagnostic JSON, not only the required acceptance rows.
    for path in sorted([*runs.glob('*.json'), *root.glob('*.json')]):
        inputs.load(path)
    trace_evidence = {case: trace_group(inputs, paths) for case, paths in exact_groups.items()}
    supplied = inputs.json[ref('exact-byte-equality.json')]
    for case, evidence in trace_evidence.items():
        recorded = supplied[case]
        require(evidence['byteIdentical'] == recorded['byteIdentical'], f'Stale byte equality verdict: {case}')
        for variant, item in evidence['artifacts'].items():
            require(item['sha256'] == recorded['digests'][variant], f'Stale trace digest: {case}/{variant}')

    raw = {name: inputs.artifact(runs / name) for name in (
        'baseline-writes.trace', 'final-writes.trace', 'baseline-matched.cpuprofile', 'final-matched.cpuprofile')}
    logs = {inputs.key(path): inputs.artifact(path) for path in sorted([*runs.glob('*.log'), *root.glob('*.log')])}
    tools = {name: inputs.artifact(root / name, source=True) for name in TOOLS}
    baseline = root / 'baseline'
    fixtures = {name: inputs.artifact(baseline / 'scripts/bench/fixtures/room-performance' / name)
                for name in ('2p.json', '4p.json', '4p-late.json', '4p-late.shape.json')}
    harnesses = {name: inputs.artifact(baseline / 'scripts/bench' / name, source=True) for name in HARNESSES}
    source = source_evidence(root / 'candidate')
    result = {
        'schemaVersion': 1, 'issue': 941, 'experiment': 'history-projection',
        'assembledAt': datetime.now(timezone.utc).isoformat(), 'decision': decision, 'source': source,
        'scope': 'Assembly preserves reported decisions and failed gates; it neither changes frozen thresholds nor grants acceptance. No prior #941 savings are counted.',
        'workload': {'fixtures': fixtures, 'harnesses': harnesses,
                     'cases': list(CASES), 'names': 'Matched and overridden Room names are independent late-game cases; stock2/stock4 guard unchanged workloads.'},
        'thresholdsArtifact': ref('history-thresholds.json'),
        'timing': {'populations': populations,
                   'comparisons': [ref(name) for name in ('archive-history-comparison-3.json', 'names-history-comparison-3.json', 'final-history-comparison-5.json')],
                   'method': 'Five fresh baseline/control/final processes per case; one complete warmup and three measured transcripts per process. Archive/names slices have three processes per late case and are diagnostic only. Frozen and contemporaneous controls remain separate.',
                   'latencyScope': 'Server command entry through durable SQLite commit and last synchronous socket sink send; excludes routing, queueing, network and client rendering. Capacity separately includes scheduling delay.'},
        'exactEquivalence': {'byteEqualityReport': ref('exact-byte-equality.json'), 'streamedVerification': trace_evidence,
                             'comparisonReports': exact_reports, 'selfTest': ref('exact-comparator-self-test.json'),
                             'method': 'Complete raw trace bytes are compared independently, including Frame/hash/private cursor, classifications and every viewer envelope. The retained comparator also supports a typed global UUID bijection; that capability does not replace the stronger byte-equality result recorded here.'},
        'physicalWrites': {'baseline': ref('baseline-writes.json'), 'candidate': ref('final-writes.json'),
                           'verdict': ref('physical-write-verdict.json'),
                           'rawTraces': {name: raw[name] for name in ('baseline-writes.trace', 'final-writes.trace')},
                           'scope': 'Completed path-filtered DB/WAL syscall bytes, separately traced; preserve SQLite temporary-file counts without treating them as DB/WAL writes.'},
        'capacity': {'contract': ref('capacity-contract.json'), 'baseline': ref('baseline-capacity.json'),
                     'candidate': ref('final-capacity.json'), 'verdict': ref('capacity-verdict.json')},
        'diagnostics': {'profiles': [ref(f'{variant}-matched-broadcast-profile.json') for variant in ('baseline', 'final')],
                        'profileSources': {name: raw[name] for name in ('baseline-matched.cpuprofile', 'final-matched.cpuprofile')},
                        'referenceCounts': [ref(f'window-reference-{variant}-matched.json') for variant in ('baseline', 'candidate')],
                        'limits': 'Profiles describe sampled main-thread ancestry. Reference probes add full-view work and count packet occurrences, not retained heap objects or bytes. Neither supplies acceptance timing or predicted savings.'},
        'verification': decision['verification'], 'commands': decision['commands'], 'logs': logs, 'analysisTools': tools,
    }
    pool = JsonPool()
    reports = {name: {**inputs.meta[name], 'report': pool.encode(value)} for name, value in inputs.json.items()}
    for name, original in inputs.json.items():
        require(canonical(pool.decode(reports[name]['report'])) == canonical(original), f'Lossy compaction: {name}')
    result.update(jsonArtifacts=reports, internedJson=pool.values, jsonEncoding={
        'referenceKey': REF,
        'commandSamplesKey': SAMPLES,
        'method': 'Recursively resolve single-key references through internedJson. A commandSamples marker contains an interned template of rows without elapsedMs and an elapsedMs vector; decode both, require equal lengths, then restore elapsedMs on each corresponding row. This reconstructs every original parsed JSON value and all unknown fields, including hashes, classifications and globalBijection arrays. Original whitespace is not encoded; raw-file SHA/bytes are retained.',
        'roundTripVerified': True, 'verifiedArtifacts': len(reports), 'uniqueValues': len(pool.values)})
    inputs.unchanged()
    return result, set(inputs.stamps)


def write_output(path, result, replace, protected):
    path = path.resolve()
    require(path.suffix == '.json' and path not in protected, 'Output must be a JSON file distinct from every input')
    require(replace or not path.exists(), f'Output already exists; choose a new path or pass --replace: {path}')
    descriptor, temporary = tempfile.mkstemp(prefix=f'.{path.name}.', dir=path.parent)
    try:
        with os.fdopen(descriptor, 'w') as stream:
            json.dump(result, stream, ensure_ascii=False, indent=2, allow_nan=False)
            stream.write('\n')
        if replace:
            os.replace(temporary, path)
        else:
            os.link(temporary, path)  # atomically refuse an output created meanwhile
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    print(f'{path}: {path.stat().st_size} bytes')


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument('--root', type=Path, default=Path(__file__).resolve().parent)
    parser.add_argument('--output', type=Path, default=Path('/home/xxh/open-agricola/docs/performance/room-history-projection-results.json'))
    parser.add_argument('--replace', action='store_true')
    parser.add_argument('--expand', type=Path, help='Expand interned JSON and commandSamples templates into complete original reports')
    args = parser.parse_args()
    if args.expand:
        result = parse(args.expand.read_bytes())
        pool = JsonPool()
        pool.values = result['internedJson']
        for artifact in result['jsonArtifacts'].values():
            artifact['report'] = pool.decode(artifact['report'])
        result.pop('internedJson')
        result['jsonEncoding'] = {'expanded': True, 'method': 'Every jsonArtifacts report is the complete original parsed JSON, with commandSamples templates and elapsedMs vectors restored to full rows.'}
        protected = {args.expand.resolve(), Path(__file__).resolve()}
    else:
        root = args.root.resolve()
        require(not args.output.resolve().is_relative_to(root), 'Keep assembled output outside the experiment input directory')
        result, protected = build(root)
    write_output(args.output, result, args.replace, protected)


if __name__ == '__main__':
    try:
        main()
    except (ValueError, OSError, KeyError, TypeError, subprocess.CalledProcessError) as error:
        print(f'History evidence assembly failed: {error}', file=sys.stderr)
        sys.exit(1)
